examples.template:
HStack {
    ForEach(filters, id: \.self) { filter in
        MonarchButton(filter, variant: .secondary, size: .sm) {
            pending = filter
            isConfirming = true
        }
        .popover(
            isPresented: Binding(
                get: { isConfirming && pending == filter },
                set: { if !$0 { isConfirming = false } }
            ),
            arrowEdge: .top
        ) {
            VStack(alignment: .leading, spacing: theme.spacing.space3) {
                Text({{title}})
                    .monarchTextStyle(.bodyStrong)
                    .accessibilityAddTraits(.isHeader)
                Text({{description}}).monarchTextStyle(.body)
                HStack(spacing: theme.spacing.space2) {
                    Spacer(minLength: 0)
                    MonarchButton("Cancel", variant: .secondary, size: .sm) { isConfirming = false }
                    MonarchButton({{confirmLabel}}, variant: .danger, size: .sm) {
                        filters.removeAll { $0 == pending }
                        isConfirming = false
                    }
                }
            }
            .foregroundStyle(theme.colors.textDefault)
            .padding(theme.spacing.space4)
            .presentationCompactAdaptation(.popover)
            .presentationBackground(theme.colors.bgRaised)
        }
    }
}

examples.setupTemplate:
@Environment(\.monarchTheme) private var theme
@State private var filters = [{{filters.0}}, {{filters.1}}]
@State private var pending = {{filters.0}}
@State private var isConfirming = false

examples.setup:
@Environment(\.monarchTheme) private var theme
@State private var filters = ["Status: Open", "Owner: Me"]
@State private var pending = "Status: Open"
@State private var isConfirming = false

examples.code:
HStack {
    ForEach(filters, id: \.self) { filter in
        MonarchButton(filter, variant: .secondary, size: .sm) {
            pending = filter
            isConfirming = true
        }
        .popover(
            isPresented: Binding(
                get: { isConfirming && pending == filter },
                set: { if !$0 { isConfirming = false } }
            ),
            arrowEdge: .top
        ) {
            VStack(alignment: .leading, spacing: theme.spacing.space3) {
                Text("Remove this filter?")
                    .monarchTextStyle(.bodyStrong)
                    .accessibilityAddTraits(.isHeader)
                Text("The list shows matching items again.").monarchTextStyle(.body)
                HStack(spacing: theme.spacing.space2) {
                    Spacer(minLength: 0)
                    MonarchButton("Cancel", variant: .secondary, size: .sm) { isConfirming = false }
                    MonarchButton("Remove", variant: .danger, size: .sm) {
                        filters.removeAll { $0 == pending }
                        isConfirming = false
                    }
                }
            }
            .foregroundStyle(theme.colors.textDefault)
            .padding(theme.spacing.space4)
            .presentationCompactAdaptation(.popover)
            .presentationBackground(theme.colors.bgRaised)
        }
    }
}

examples.setup:
@Environment(\.monarchTheme) private var theme
@State private var isConfirming = false
@State private var isRevoked = false

examples.code:
MonarchButton("Revoke invitation", variant: .ghost) { isConfirming = true }
    .popover(isPresented: $isConfirming, arrowEdge: .top) {
        VStack(alignment: .leading, spacing: theme.spacing.space3) {
            Text("Revoke this invitation?")
                .monarchTextStyle(.bodyStrong)
                .accessibilityAddTraits(.isHeader)
            Text("The link in the email stops working.").monarchTextStyle(.body)
            HStack {
                MonarchButton("Cancel", size: .sm) { isConfirming = false }
                MonarchButton("Revoke", variant: .danger, size: .sm) {
                    isRevoked = true
                    isConfirming = false
                }
            }
        }
        .foregroundStyle(theme.colors.textDefault)
        .padding(theme.spacing.space4)
        .presentationCompactAdaptation(.popover)
        .presentationBackground(theme.colors.bgRaised)
    }
